 "<b>AR</b>": "<b>AR</b>",
 "<b style=\"font-size:26px\">Aina Roig</b><br><span style=\"color:#008f7e\">Directora de arte editorial</span><br>Rediseñó un diario en doce columnas.": "<b style=\"font-size:26px\">Aina Roig</b><br><span style=\"color:#008f7e\">Art director editoriale</span><br>Ha riprogettato un quotidiano su dodici colonne.",
 "<b>LT</b>": "<b>LT</b>",
 "<b style=\"font-size:26px\">Lucas Tena</b><br><span style=\"color:#008f7e\">Profesor de diseño</span><br>Treinta años enseñando a dejar blanco.": "<b style=\"font-size:26px\">Lucas Tena</b><br><span style=\"color:#008f7e\">Docente di design</span><br>Trent'anni a insegnare a lasciare bianco.",
